sys_script.script:
(function executeRule(current, previous /*null when async*/) {
  if (!current.isValidRecord()) return;
  if (current.state.changes()) {
    // Gera o HTML no servidor (mesma lógica do client)
    var state = current.state.toString();
    var html = '';
    // Replique a lógica de buildIndicatorHtml aqui (simplificada)
    if (state === 'Draft') {
      html = 'Draft ◻ Published ◻ Follow-up ◻ Closed';
    } else if (state === 'Published') {
      html = '✅ Draft ➡ Published ◻ Follow-up ◻ Closed';
    } else if (state === 'Follow-up') {
      html = '✅ Draft ✅ Published ➡ Follow-up ◻ Closed';
    } else if (state === 'Closed') {
      html = '✅ Draft ✅ Published ✅ Follow-up ➡ Closed';
    }
    current.status_indicator = html;
    // Atualiza sem reexecutar workflows adicionais
    current.setWorkflow(false);
    current.update();
  }
})(current, previous);
